cd $TMPDIR && node --input-type=module -e "
import {reserve} from '/tmp/eval/home/cwd/stock.js';
import {store} from '/tmp/eval/home/cwd/store.js';
const s=store(); console.log('serial:', await reserve(s,'a'), await reserve(s,'a'), s.value());
const t=store(); console.log('overlapping:', await Promise.all([reserve(t,'a'),reserve(t,'a')]), t.value());
"
